-- ---- Default admin user (change the password after first login!) ----
IF NOT EXISTS (SELECT 1 FROM proj.TBL_USERS WHERE UserName = 'admin')
BEGIN
    INSERT INTO proj.TBL_USERS (UserCode, UserName, PasswordHash, FullName, Email, IsActive, IsLocked, CreatedBy, CreatedDate, Theme)
    VALUES ('ADM-001', 'admin',
            LOWER(CONVERT(VARCHAR(64), HASHBYTES('SHA2_256', 'Admin@123'), 2)),  -- password: Admin@123
            'System Administrator', NULL, 1, 0, 'SYSTEM', GETDATE(), 'ocean-blue');

    INSERT INTO proj.TBL_USER_ROLES (UserId, RoleId)
    SELECT u.UserId, r.RoleId
    FROM proj.TBL_USERS u
    CROSS APPLY (SELECT TOP 1 RoleId FROM proj.TBL_ROLES WHERE RoleName LIKE '%admin%' ORDER BY RoleId) r
    WHERE u.UserName = 'admin';
END
GO

